type agreementUnusedParagraphDiagnosticSingle struct {
	Field, Index, Start int
	Body                string
	Diagnostics         []render.Diagnostic
}
type agreementUnusedParagraphDiagnosticWitness struct {
	Name, Body, Target, Selected    string
	Diagnostics, PrivateDiagnostics []render.Diagnostic
	Indices                         []int
	Singles                         []agreementUnusedParagraphDiagnosticSingle
}

type agreementUnusedParagraphDiagnosticOwner struct {
	Field, Definition, Root, Node, Line int
	Label                               string
}

// A plain field binds one consumed discarded definition and one whole paragraph line.
func agreementUnusedParagraphDiagnosticPhysical(body string, check *agreementNativeCheckSource, tree *agreementNativeProseAddressTree, target string) ([]agreementUnusedParagraphDiagnosticOwner, bool) {
	if !tree.Valid || target == "" {
		return nil, false
	}
	var owners []agreementUnusedParagraphDiagnosticOwner
	used := map[graph.Span]bool{}
	for fi, f := range check.Fields {
		if f.Code || f.Comment || f.Escaped || f.DefinitionOwner >= 0 || f.CodeOwner >= 0 || len(f.Targets) != 1 || f.Targets[0] != target || f.Word != "[["+target+"]]" {
			continue
		}
		if f.Span.Start < 0 || f.Span.Stop > len(body) || f.Span.Stop <= f.Span.Start || body[f.Span.Start:f.Span.Stop] != f.Word {
			return nil, false
		}
		found := false
		candidate := agreementUnusedParagraphDiagnosticOwner{}
		for di, d := range tree.Definitions {
			if !d.Found || d.Root < 1 || d.Root >= len(tree.Trees) || d.Node != 0 || d.Label == "" || d.Bounds.Parent == "" || d.Bounds.Span.Start < 0 || d.Bounds.Span.Stop > len(body) || d.Bounds.Span.Stop <= d.Bounds.Span.Start || d.Bounds.Label.Start < d.Bounds.Span.Start || d.Bounds.Label.Stop > d.Bounds.Span.Stop || d.Bounds.Label.Stop <= d.Bounds.Label.Start || len(tree.Trees[d.Root]) == 0 || tree.Trees[d.Root][0].Kind != extast.KindFootnote.String() || f.Span.Start < d.Bounds.Span.Start || f.Span.Stop > d.Bounds.Span.Stop {
				continue
			}
			for ni, n := range tree.Trees[d.Root] {
				if n.Kind != ast.KindParagraph.String() {
					continue
				}
				for li, line := range n.Lines {
					if line.Start < 0 || line.Stop > len(body) || line.Stop <= line.Start || f.Span.Start < line.Start || f.Span.Stop > line.Stop {
						continue
					}
					if found {
						return nil, false
					}
					found = true
					candidate = agreementUnusedParagraphDiagnosticOwner{Field: fi, Definition: di, Root: d.Root, Node: ni, Line: li, Label: d.Label}
				}
			}
		}
		if found {
			if used[f.Span] {
				return nil, false
			}
			used[f.Span] = true
			owners = append(owners, candidate)
		}
	}
	return owners, len(owners) > 0
}

// Private names replace only targets in the independently declared paragraph set.
func agreementUnusedParagraphDiagnosticPrivate(body, target string, owners []agreementUnusedParagraphDiagnosticOwner, check *agreementNativeCheckSource) (string, []agreementMixedRename, bool) {
	if target == "" || len(owners) == 0 || strings.Contains(body, "q") {
		return "", nil, false
	}
	tree := agreementNativeProseAddressTreeReading(body, nil)
	physical, ok := agreementUnusedParagraphDiagnosticPhysical(body, check, &tree, target)
	if !ok {
		return "", nil, false
	}
	private := []byte(body)
	var changes []agreementMixedRename
	used := map[int]bool{}
	for _, owner := range owners {
		if owner.Field < 0 || owner.Field >= len(check.Fields) || used[owner.Field] || !slices.Contains(physical, owner) {
			return "", nil, false
		}
		used[owner.Field] = true
		field := check.Fields[owner.Field]
		start, stop := field.Span.Start+2, field.Span.Stop-2
		if body[start:stop] != target {
			return "", nil, false
		}
		replacement := strings.Repeat("q", len(target))
		copy(private[start:stop], replacement)
		changes = append(changes, agreementMixedRename{Field: owner.Field, Span: graph.Span{Start: start, Stop: stop}, Old: target, New: replacement})
	}
	return string(private), changes, true
}

func agreementUnusedParagraphDiagnosticProducers(t *testing.T, body, target string, native agreementNativeOwnerSource, check *agreementNativeCheckSource) (physicalFields, diagnosticFields []agreementUnusedParagraphDiagnosticOwner, targetChanges []agreementMixedRename, projectedBody string, valid bool) {
	t.Helper()
	tree := agreementNativeProseAddressTreeReading(body, nil)
	physical, ok := agreementUnusedParagraphDiagnosticPhysical(body, check, &tree, target)
	if !ok {
		return nil, nil, nil, "", false
	}
	raw, page := agreementIsolatedPage(t, agreementCase{Body: body})
	parts, pok := agreementCodeWindowParts(raw.HTML)
	if !pok {
		return nil, nil, nil, "", false
	}
	var owners []agreementUnusedParagraphDiagnosticOwner
	var changes []agreementMixedRename
	whole := []byte(body)
	used := map[int]bool{}
	for _, owner := range physical {
		private, oneChanges, valid := agreementUnusedParagraphDiagnosticPrivate(body, target, []agreementUnusedParagraphDiagnosticOwner{owner}, check)
		if !valid {
			continue
		}
		pr, pp := agreementIsolatedPage(t, agreementCase{Body: private})
		privateParts, validParts := agreementCodeWindowParts(pr.HTML)
		if !validParts || !cmp.Equal(native, agreementNativeOwnerReading(private)) || !cmp.Equal(tree, agreementNativeProseAddressTreeReading(private, nil)) || raw.HTML != pr.HTML || !cmp.Equal(page, pp) || !cmp.Equal(parts, privateParts) || len(raw.Diagnostics) != len(pr.Diagnostics) {
			continue
		}
		index := -1
		unique := true
		for di := range raw.Diagnostics {
			if cmp.Equal(raw.Diagnostics[di], pr.Diagnostics[di]) {
				continue
			}
			if index >= 0 {
				unique = false
				break
			}
			index = di
		}
		if !unique || index < 0 || used[index] {
			continue
		}
		a, b := raw.Diagnostics[index], pr.Diagnostics[index]
		change := oneChanges[0]
		if a.Kind != render.DiagWikilinkBroken || a.Target != target || b.Target != change.New || a.Kind != b.Kind || a.Section != b.Section || a.Block != b.Block || b.Message != strings.ReplaceAll(a.Message, "\""+target+"\"", "\""+change.New+"\"") {
			continue
		}
		used[index] = true
		owners = append(owners, owner)
		changes = append(changes, change)
		copy(whole[change.Span.Start:change.Span.Stop], change.New)
	}
	return physical, owners, changes, string(whole), len(owners) > 0
}

// A discarded diagnostic moves with its physical target while public faces stay fixed.
func agreementUnusedParagraphDiagnosticSignedProjection(before, after []agreementFailure, page *agreementHTML, targets []string, selected *agreementFailure, fields int) bool {
	if selected == nil || fields < 1 || fields != selected.Multiplicity || selected.Tuple.Target == "" {
		return false
	}
	target := selected.Tuple.Target
	replacement := strings.Repeat("q", len(target))
	counts := map[string]int{}
	for _, name := range targets {
		counts[name]++
	}
	visible := map[string]int{}
	for _, citation := range page.Citations {
		if citation.SourceRole == "" && citation.Target != "" {
			visible[citation.Target]++
		}
	}
	if counts[target] < fields || counts[replacement] != 0 || visible[replacement] != 0 {
		return false
	}
	signed := func(name string, delta int) string {
		if delta == 0 {
			return ""
		}
		direction := "judge-only"
		if delta < 0 {
			direction = "page-only"
			delta = -delta
		}
		f := agreementFailure{Property: "P1", Identity: "citation-occurrences", Tuple: agreementCitation{Target: name}, Direction: direction, Multiplicity: delta}
		return agreementSignature(&f)
	}
	oldP1 := map[string]int{}
	for i := range before {
		f := &before[i]
		if f.Property == "P1" && (f.Tuple.Target == target || f.Tuple.Target == replacement) {
			oldP1[agreementSignature(f)]++
		}
	}
	declared := map[string]int{}
	if signature := signed(target, counts[target]-visible[target]); signature != "" {
		declared[signature] = 1
	}
	if !maps.Equal(oldP1, declared) {
		return false
	}
	expected := maps.Clone(agreementMixedCurrent(before))
	signature := agreementSignature(selected)
	if expected[signature] != 1 {
		return false
	}
	delete(expected, signature)
	renamed := *selected
	renamed.Tuple.Target = replacement
	expected[agreementSignature(&renamed)]++
	for key := range oldP1 {
		delete(expected, key)
	}
	if key := signed(target, counts[target]-fields-visible[target]); key != "" {
		expected[key]++
	}
	expected[signed(replacement, fields)]++
	return maps.Equal(expected, agreementMixedCurrent(after))
}

func agreementUnusedParagraphDiagnosticSource(body, target string) (*agreementUnusedParagraphDiagnosticSourceWitness, *agreementUnusedParagraphDiagnosticVariant, bool) {
	witnesses := agreementUnusedParagraphDiagnosticSources()
	for wi := range witnesses {
		w := &witnesses[wi]
		if w.Body != body {
			continue
		}
		for vi := range w.Variants {
			v := &w.Variants[vi]
			if v.Target == target {
				return w, v, true
			}
		}
		return nil, nil, false
	}
	return nil, nil, false
}

// Every changed diagnostic belongs to one declared HTML block field.
func agreementUnusedParagraphDiagnosticDifference(c agreementCase, f *agreementFailure, raw string, page *agreementHTML, diagnostics []render.Diagnostic, failures []agreementFailure) (kind, authority, wrong string) {
	if f == nil || page == nil || c.Title != "" || len(c.Companions) != 0 || f.Property != "P0" || f.Identity != "diagnostic-html" || f.Direction != "diagnostic-only" || f.Multiplicity < 1 || f.Tuple.SourceRole != "" || f.Tuple.State != "wikilink-broken" || f.Tuple.Section != "" || f.Fragment != "" || f.Cut != "" || f.PagePresent || f.JudgeAccepted || f.ExcerptFound {
		return "", "", ""
	}
	records := agreementUnusedParagraphDiagnosticWitnesses()
	for ri := range records {
		r := &records[ri]
		if c.Body != r.Body || f.Tuple.Target != r.Target {
			continue
		}
		if agreementSignature(f) != r.Selected || !cmp.Equal(diagnostics, r.Diagnostics) {
			return "", "", ""
		}
		w, v, found := agreementUnusedParagraphDiagnosticSource(c.Body, r.Target)
		if !found {
			return "", "", ""
		}
		native := agreementNativeOwnerReading(c.Body)
		check := agreementNativeCheckReading(c.Body, native)
		tree := agreementNativeProseAddressTreeReading(c.Body, nil)
		parts, pok := agreementCodeWindowParts(raw)
		physical, ok := agreementUnusedParagraphDiagnosticPhysical(c.Body, &check, &tree, r.Target)
		private, changes, valid := agreementUnusedParagraphDiagnosticPrivate(c.Body, r.Target, v.Owners, &check)
		if !pok || !ok || !valid || len(v.Owners) != f.Multiplicity || len(r.Indices) != len(v.Owners) || !cmp.Equal(physical, v.Physical) || !cmp.Equal(changes, v.Changes) || private != v.Body || !cmp.Equal(native, w.Native) || !cmp.Equal(check, w.Check) || !cmp.Equal(tree, w.Tree) || !cmp.Equal(agreementNativeCodePayloadSites(c.Body), w.Sites) || !cmp.Equal(agreementNativeHTMLAddressSites(c.Body), w.HTML) || !cmp.Equal(judge.LinkTargets(c.Body), w.Targets) || !cmp.Equal(parts, w.Parts) || !cmp.Equal(*page, w.Page) || !maps.Equal(agreementMixedCurrent(failures), w.Signatures) {
			return "", "", ""
		}
		return "debt", "#1011 stage 5", "page-diagnostic"
	}
	return "", "", ""
}

